<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\Outbox\Application\Service;

use DateTimeImmutable;
use Throwable;
use Civi\Lughauth\Features\Notification\Message\Domain\Message;
use Civi\Lughauth\Features\Notification\Message\Domain\MessageAttributes;
use Civi\Lughauth\Features\Notification\Message\Domain\Gateway\MessageFilter;
use Civi\Lughauth\Features\Notification\Message\Domain\Gateway\MessageReadGateway;
use Civi\Lughauth\Features\Notification\Message\Domain\Gateway\MessageWriteGateway;
use Civi\Lughauth\Features\Notification\Outbox\Domain\Gateway\SmtpMailSenderGateway;
use Civi\Lughauth\Features\Notification\Outbox\Domain\Model\OutboundMail;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\SmtpOutboundConfig;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\Gateway\SmtpOutboundConfigReadGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

/**
 * Dispatches pending outbox messages via SMTP and cleans up messages past the retention period.
 *
 * Message lifecycle:
 *   Pending  — retries >= 0, sendAt IS NULL or sendAt <= now.
 *   Sent     — deleted immediately after a successful send.
 *   Failed   — retry counter incremented; retried until retries >= maxRetries.
 *
 * Rate limiting: at most DISPATCH_RATE messages are dispatched per cycle.
 */
class NotificationDispatchService
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    private const int DEFAULT_MAX_RETRIES   = 3;
    private const int DISPATCH_RATE         = 10;
    private const int RETENTION_HOURS       = 168; // 7 days

    
    public function __construct(
        private readonly MessageReadGateway $messageReader,
        private readonly MessageWriteGateway $messageWriter,
        private readonly SmtpOutboundConfigReadGateway $smtpConfigReader,
        private readonly SmtpMailSenderGateway $mailSender,
    ) {
    }

    /**
     * Processes pending outbox messages, up to DISPATCH_RATE per cycle.
     */
    public function dispatch(): void
    {
        $this->logDebug("Running outbox notification dispatch");
        $span = $this->startSpan("outbox.dispatch");
        try {
            $now        = new DateTimeImmutable('now');
            $messages   = $this->messageReader->list(new MessageFilter())->values();
            $pending    = array_filter($messages, fn(Message $m) => $this->isPending($m, $now));
            $batch      = array_slice(array_values($pending), 0, self::DISPATCH_RATE);

            foreach ($batch as $message) {
                $this->dispatchMessage($message);
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    /**
     * Deletes sent messages older than RETENTION_HOURS.
     */
    public function cleanup(): void
    {
        $this->logDebug("Running outbox notification cleanup");
        $span   = $this->startSpan("outbox.cleanup");
        try {
            $cutoff   = new DateTimeImmutable('-' . self::RETENTION_HOURS . ' hours');
            $messages = $this->messageReader->list(new MessageFilter())->values();

            foreach ($messages as $message) {
                if ($message->getCreatedAt() < $cutoff) {
                    $this->messageWriter->delete($message);
                }
            }

            $this->logDebug("Outbox cleanup finished; retention cutoff={cutoff}", ['cutoff' => $cutoff->format(\DateTimeInterface::ATOM)]);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    // ---------------------------------------------------------------------------
    // State predicates
    // ---------------------------------------------------------------------------

    /**
     * Returns true if the message should be dispatched now.
     * A message is pending when its sendAt is null (immediate) or has already passed.
     */
    private function isPending(Message $message, DateTimeImmutable $now): bool
    {
        $sendAt = $message->getSendAt();
        return null === $sendAt || $sendAt <= $now;
    }

    // ---------------------------------------------------------------------------
    // Dispatch logic
    // ---------------------------------------------------------------------------

    /**
     * Sends a single pending outbox message.
     * On success: deleted. On failure: retry counter incremented.
     */
    private function dispatchMessage(Message $message): void
    {
        $smtpConfig = $this->resolveSmtpConfig($message);
        $maxRetries = $smtpConfig?->getMaxRetries() ?? self::DEFAULT_MAX_RETRIES;

        if ($message->getRetries() >= $maxRetries) {
            $this->logWarning(
                "Message uid={uid} exceeded max retries ({max}), skipping",
                ['uid' => $message->uid(), 'max' => $maxRetries]
            );
            return;
        }

        try {
            $mail = $this->buildMail($message);

            if (null !== $smtpConfig) {
                $this->mailSender->sendWithConfig($smtpConfig, $mail);
            } else {
                $this->mailSender->send($mail);
            }

            $this->messageWriter->delete($message);
            $this->logDebug("Dispatched message uid={uid}", ['uid' => $message->uid()]);
        } catch (Throwable $ex) {
            $this->logWarning(
                "Failed to dispatch message uid={uid}, incrementing retries",
                ['uid' => $message->uid()]
            );
            $this->incrementRetries($message);
        }
    }

    /**
     * Increments the retry counter by one.
     * Exceptions during the update are caught so they do not mask the original send failure.
     */
    private function incrementRetries(Message $message): void
    {
        try {
            $attrs   = (new MessageAttributes())->retries($message->getRetries() + 1);
            $updated = $message->update($attrs);
            $this->messageWriter->update($message, $updated);
        } catch (Throwable $ex) {
            $this->logError(
                "Failed to increment retries for message uid={uid}",
                ['uid' => $message->uid()]
            );
        }
    }

    // ---------------------------------------------------------------------------
    // SMTP resolution and mail building
    // ---------------------------------------------------------------------------

    /**
     * Resolves the SMTP config: tenant-specific first, then global (tenant IS NULL).
     */
    private function resolveSmtpConfig(Message $message): ?SmtpOutboundConfig
    {
        $tenant = $message->getTenant();

        if (null !== $tenant) {
            $config = $this->smtpConfigReader->findOneByTenant($tenant);
            if (null !== $config) {
                return $config;
            }
        }

        return $this->smtpConfigReader->findOneByTenant(null);
    }

    /**
     * Constructs an OutboundMail from the stored message content.
     *
     * The content field is expected to be a JSON object with subject, html, and text keys.
     * When parsing fails the content is treated as raw HTML.
     */
    private function buildMail(Message $message): OutboundMail
    {
        $raw  = $message->getContent();
        $data = json_decode($raw, true);

        if (is_array($data) && isset($data['html'])) {
            return new OutboundMail(
                recipient:   $message->getTarget(),
                htmlContent: $data['html'],
                subject:     $data['subject'] ?? '',
                textContent: $data['text'] ?? null,
            );
        }

        return new OutboundMail(
            recipient:   $message->getTarget(),
            htmlContent: $raw,
        );
    }
}
